presets.css:
.device {
  --glass: rgba(255,255,255,.62);
  --glass-strong: rgba(255,255,255,.9);
  --glass-border: rgba(0,0,0,.05);
}
html[data-theme="dark"] .device {
  --glass: rgba(28,28,32,.68);
  --glass-strong: rgba(40,40,46,.9);
  --glass-border: rgba(255,255,255,.08);
}
.wg-profile,.wg-hero,.wg-note,.wg-quote {
  background: rgba(255,255,255,.92);
  border: 1px solid rgba(0,0,0,.05);
  box-shadow: 0 0 0 0.5px rgba(255,255,255,.9);
  backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px);
  border-radius: 18px;
}
html[data-theme="dark"] .wg-profile,
html[data-theme="dark"] .wg-hero,
html[data-theme="dark"] .wg-note,
html[data-theme="dark"] .wg-quote {
  background: rgba(36,36,36,.92);
  border-color: rgba(255,255,255,.08);
  box-shadow: 0 0 0 0.5px rgba(36,36,36,.9);
}
